use verus::prelude::*;

verus! {

  fn copy(a: &Vec<u64>) -> (b: Vec<u64>)
    ensures
      // The returned vector b has the same length as a
      b.len() == a.len() &&
      // For every index i in [0, a.len()), b[i] == a[i]
      forall(|i: usize| i < a.len() ==> b[i] == a[i]) &&
      // The order of elements is preserved (already implied by above)
      true
  {
    // We require that input length is at most 100 as per the problem statement
    assert(a.len() <= 100);

    // Initialize an empty vector with capacity a.len()
    let mut b = Vec::<u64>::new();
    // Loop variable i: index copying elements
    let mut i: usize = 0;

    // We use a while loop with invariants and decreases to satisfy verification
    while i < a.len()
      invariant
        i <= a.len() &&
        // For every j in [0, i), b[j] == a[j]
        forall(|j: usize| j < i ==> b[j] == a[j]) &&
        // b.len() == i (elements appended so far)
        b.len() == i
      decreases a.len() - i
    {
      b.push(a[i]);
      i += 1;
    }

    b
  }
}